const screenTone = result => result?.reviewRequired ? 'caution' : result?.eligible ? 'value' : 'neutral';
const renalRoundingNote = (value, raw) => Number.isInteger(value) && Number.isFinite(raw) && raw !== value ? ` · ${raw < value ? 'below' : 'above'} ${value} mL/min before rounding` : '';
