  const diagnosis = state.note.diagnosisCategory, followUp = state.context === 'follow-up';
  const contextual = diagnosis === 'sah' ? [['hunt-hess','Hunt–Hess'],['wfns','WFNS'],['modified-fisher','Modified Fisher'],['phases','PHASES']]
    : diagnosis === 'ich' ? [['ich-volume','ICH volume'],['ich-score','ICH severity']]
    : diagnosis === 'tia' ? [['abcd2','ABCD²'],['nascet','NASCET'],['chadsvasc','CHA₂DS₂-VASc'],['has-bled','HAS-BLED']]
    : diagnosis === 'ischemic' ? followUp ? [['rope','RoPE'],['pascal','PASCAL'],['nascet','NASCET'],['chadsvasc','CHA₂DS₂-VASc'],['has-bled','HAS-BLED']]
      : [['aspects-regions','ASPECTS'],['pc-aspects-regions','pc-ASPECTS'],['mtici','mTICI'],['nascet','NASCET']] : [];
  const links = [['gcs','GCS'],['crcl','Renal calculation'],['mrs-descriptors','mRS descriptors'],...contextual,...(followUp ? [['phq2','PHQ-2'],['stop-bang','STOP-BANG']] : [])];
  return <Disclosure title="Calculators for this encounter"><nav aria-label="Encounter calculators"><ul className="tool-links">{links.map(([id,label]) => <li key={id}><a href={`#/encounter/${id}`}>{label}</a></li>)}<li><a href="#/tools">All calculators</a></li></ul></nav></Disclosure>;
