  const note = (key, value) => update(prev => ({ ...prev, note: { ...prev.note, [key]: value } }));
  const group = (name, key, value) => update(prev => ({ ...prev, [name]: { ...prev[name], [key]: value } }));
  const clockOccurrence = (prefix, label) => <TimestampOccurrence label={label} value={n[`${prefix}Date`] && n[`${prefix}Time`] ? `${n[`${prefix}Date`]}T${n[`${prefix}Time`]}` : ''} instant={encounterClockTimestamp(n, prefix)} onChange={instant => note(`${prefix}Clock`, instant ? { value: `${n[`${prefix}Date`]}T${n[`${prefix}Time`]}`, instant } : null)} />;
