  const groupControl = (name, Control, key, label, props) => <Control label={label} value={s[name][key]} onChange={v => group(name, key, v)} {...props} />;
  const noteFields = fields => fields.map(([Control, key, label, props]) => <React.Fragment key={key}>{noteControl(Control, key, label, props)}{key === 'ctTime' && clockOccurrence('ct', 'Head CT')}{key === 'ctaTime' && clockOccurrence('cta', 'CTA')}</React.Fragment>);
