  const setClockNow = (prefix, instant) => {
    const value = localTimestamp(instant), [date, time] = value.split('T');
    update(prev => ({ ...prev, note: { ...prev.note, [`${prefix}Date`]: date, [`${prefix}Time`]: time, [`${prefix}Clock`]: { value, instant: new Date(instant).toISOString() } } }));
  };
  const acuteIschemic = s.context === 'acute' && n.diagnosisCategory === 'ischemic';
  const gcs = reviewedGcs(s.gcs);
  const volume = encounterVolume(s.volume);
  const age = numericInput(n.age, { min: 0, max: 120 });
