  // A cerebellar or brainstem location contradicting 'Infratentorial origin: No' withholds the score.
  const ichLocationConflict = n.diagnosisCategory === 'ich' && ['Cerebellar', 'Brainstem'].includes(s.details?.ichLocation) && s.ich.infratentorial === false;
  const ich = n.diagnosisCategory === 'ich' && age !== null && gcs !== null && volume && !volume.unitWarning && !ichLocationConflict && typeof s.ich.ivh === 'boolean' && typeof s.ich.infratentorial === 'boolean' ? calculateICHScore({ gcs: gcs <= 4 ? 'gcs34' : gcs <= 12 ? 'gcs512' : 'gcs1315', age80: age >= 80, volume30: volume.isLarge, ivh: s.ich.ivh, infratentorial: s.ich.infratentorial, criteriaReviewed: true }) : null;
