  const screenNote = { ...active, ivtContraindicationsReviewed: n.ivtContraindicationsReviewed && safetyMissing.length === 0 };
  const screen = acuteIschemic ? evaluateVideoTreatment({ note: screenNote, clock: timing.clock ? { total: timing.hours, label: timing.label } : null, aspects: s.aspects, pcAspects: s.pcAspects, now: new Date(now) }) : null;
  const exposure = acuteIschemic ? assessAnticoagulantExposure(active, new Date(now)) : null;
  const wake = acuteIschemic ? evaluateWakeUpScreen(active, new Date(now)) : null;
  const administration = acuteIschemic && s.actions.administered && s.drug && validTimestamp(s.actions.administrationTime, now);
  const schedule = administration ? computeNeurocheckSchedule(s.actions.administrationTime) : null;
  const nextCheck = schedule?.checks.find(check => check.at.getTime() > now);
  // Entered values that conflict with a bleeding item count as a concern even if answered No.
  const daptConcerns = SAFETY_ITEMS.filter(item => DAPT_BLEEDING_ITEMS.includes(item.id) && (n.tnkContraindicationChecklist[item.id] === true || signals[item.id]?.conflict))
    .map(item => n.tnkContraindicationChecklist[item.id] === true ? item.label : `${item.label} (entered ${signals[item.id].reason})`);
  const daptConcern = daptConcerns.length > 0;
  const reperfusionReview = daptReperfusionReview(s);
  const anticoagulationReview = daptAnticoagulationReview(s);
  const dapt = s.context === 'acute' && ['ischemic', 'tia'].includes(n.diagnosisCategory) ? recommendAcuteDAPT({ ...s.dapt, age: n.age, anticoagulationExcluded: anticoagulationReview.excluded, ichRisk: daptConcern ? 'high' : s.dapt.ichRisk, strokeType: n.diagnosisCategory, nihss: exam.total, timeFromOnsetH: timing.hours, hemorrhageExcluded: n.ctHemorrhageStatus === 'absent', reperfusionExcluded: reperfusionReview.excluded }) : null;
  const warning = outputWarnings(s);
  const bpParts = [0, 1].map(index => (n.presentingBP || '').split('/')[index]?.trim() || '');
  const setBp = (index, value) => { const parts = [...bpParts]; parts[index] = value; note('presentingBP', parts.some(Boolean) ? `${parts[0]}/${parts[1]}` : ''); };
  const [sbpValue, dbpValue] = bpParts.map(value => numericInput(value, { min: 1, max: 400 }));
  // The countdown ticks every second, so it is a timer (not announced); this announces threshold crossings only.
  const lkwMilestone = acuteIschemic && timing.clock && !timing.invalid && !n.lkwUnknown ? timing.clock.toLateEvtClosed ? '24 h from last known well has passed.' : timing.clock.toLyticClosed ? '4.5 h from last known well has passed.' : timing.clock.toLyticMs <= 30 * 60000 ? 'Under 30 minutes left in the 4.5 h window.' : '' : null;
  const bpOrderIssue = sbpValue !== null && dbpValue !== null && sbpValue <= dbpValue;
  const perfusionOrderIssue = (() => { const core = numericInput(n.coreVolume, { min: 0 }), total = numericInput(n.penumbraVolume, { min: 0 }); return core !== null && total !== null && total < core; })();
